(()=>{const key='popomo-home-designs',sharedKey='popomo-shared-designs',likesKey='popomo-design-likes';const read=(storage,k,fallback)=>{try{return JSON.parse(storage.getItem(k)||JSON.stringify(fallback));}catch{return fallback;}};
function list(){const v=read(sessionStorage,key,[]);return Array.isArray(v)?v:[];}
function shared(){const v=read(localStorage,sharedKey,[]);return Array.isArray(v)?v:[];}
function publicCopy(d){const s=d.flowState;return {id:d.id,name:d.name,model:d.model,phoneColor:d.phoneColor,source:d.source,template:d.template,image:d.cover||d.image,cover:d.cover||d.image,author:d.author||'POPOMO creator',authorAvatar:d.authorAvatar||'./assets/avatars/avatar-1-v30.svg',published:true,publishedAt:d.publishedAt||Date.now(),updatedAt:d.updatedAt,flowState:s?{model:s.model,phoneColor:s.phoneColor,brand:s.brand,template:s.template,background:s.background,layers:s.layers,editor:{source:s.editor?.source||d.source}}:undefined};}
function save(design){const all=list(),previous=all.find(item=>item.id===design.id),next={...previous,...design,id:design.id||crypto.randomUUID(),printCount:previous?.printCount??design.printCount??0,updatedAt:Date.now()};if(next.published&&!next.sharingConsentAt)next.published=false;const result=[next,...all.filter(item=>item.id!==next.id)];const publicAll=shared(),newPublic=next.published?[publicCopy(next),...publicAll.filter(d=>d.id!==next.id)]:publicAll.filter(d=>d.id!==next.id);localStorage.setItem(sharedKey,JSON.stringify(newPublic));try{sessionStorage.setItem(key,JSON.stringify(result));}catch(e){localStorage.setItem(sharedKey,JSON.stringify(publicAll));throw e;}return next;}
function withdraw(id){const d=list().find(d=>d.id===id);if(!d)return null;return save({...d,published:false,sharingConsentAt:null});}
function printed(id,quantity){const all=list(),item=all.find(item=>item.id===id);if(!item)return null;item.printCount=(Number(item.printCount)||0)+quantity;item.lastPrintedAt=Date.now();sessionStorage.setItem(key,JSON.stringify(all));return item;}
function liked(id){return read(localStorage,likesKey,[]).includes(id);}
function toggleLike(id){let ids=read(localStorage,likesKey,[]);ids=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id];localStorage.setItem(likesKey,JSON.stringify(ids));return ids.includes(id);}
window.PopomoDesigns={list,save,printed,shared,withdraw,liked,toggleLike};})();
